/**
 * Custom Static HTML Root — Sekundo Web (`+html.tsx`)
 *
 * Ensures that static SSR HTML generated by `expo export -p web` immediately
 * applies the deep space obsidian background (`#07090E`) and neutralizes
 * React Navigation's default light wrapper (`rgba(242,242,242,1.00)`) in `<head>`
 * before the JS bundle finishes downloading on mobile networks.
 */

import { ScrollViewStyleReset } from 'expo-router/html';
import type { PropsWithChildren } from 'react';

export default function Root({ children }: PropsWithChildren) {
  return (
    <html lang="pt-BR" style={{ backgroundColor: '#07090E' }}>
      <head>
        <meta charSet="utf-8" />
        <meta httpEquiv="X-UA-Compatible" content="IE=edge" />
        <meta
          name="viewport"
          content="width=device-width, initial-scale=1, shrink-to-fit=no, viewport-fit=cover"
        />
        <meta name="theme-color" content="#07090E" />
        <meta name="apple-mobile-web-app-capable" content="yes" />
        <meta name="apple-mobile-web-app-status-bar-style" content="black-translucent" />
        <ScrollViewStyleReset />
        <style
          id="sekundo-dark-ssr"
          dangerouslySetInnerHTML={{
            __html: `
              html, body, #root {
                background-color: #07090E !important;
                color: #F8FAFC;
              }
              div[style*="background-color:rgba(242,242,242"],
              div[style*="background-color: rgb(242, 242, 242)"],
              div[style*="background-color:#f2f2f2"],
              div[style*="background-color: #f2f2f2"] {
                background-color: transparent !important;
              }
            `,
          }}
        />
      </head>
      <body style={{ backgroundColor: '#07090E' }}>{children}</body>
    </html>
  );
}
